BEGIN;

INSERT INTO public.subjects (slug, name, description, color, sort_order, is_active)
VALUES ('gcp-pca-g',
        'GCP PCA 誤答復習セット',
        '模試で間違えた問題を原文のまま収録した復習セット（全19問）。問題文と選択肢は出題元のまま、解説のみ前提知識ゼロで読めるよう書き下ろし。設問番号は模試の番号を保持している。',
        '#db4437', 27, true)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.categories (subject_id, name, color, sort_order)
SELECT s.id, v.name, v.color, v.sort_order
FROM public.subjects s
JOIN (VALUES
  ('設計・計画', '#58a6ff', 0),
  ('インフラのプロビジョニングと管理', '#3fb950', 1),
  ('セキュリティとコンプライアンス', '#d2a8ff', 2),
  ('プロセスの分析と最適化', '#f0883e', 3),
  ('実装の管理', '#ff7b72', 4),
  ('信頼性の確保', '#a5d6ff', 5)
) AS v(name, color, sort_order) ON s.slug = 'gcp-pca-g'
WHERE NOT EXISTS (
  SELECT 1 FROM public.categories c WHERE c.subject_id = s.id AND c.name = v.name
);

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES

  ('gcp-pca-g-q1', '設計・計画',
   'あなたは大手Eコマース企業のクラウドアーキテクトです。現在、自社のオンプレミス環境で稼働しているApache SparkおよびHadoopクラスターの処理負荷が、今後のビジネス成長に伴い大幅に増加すると予測されています。運用負荷を抑え、既存のプログラム資産への変更を最小限に留めたまま、クラウドの拡張性を活用したいと考えています。要件を達成するためにあなたがすべきことは何ですか？',
   NULL::text,
   '["Google Compute Engine", "BigQuery", "Cloud Dataproc", "Google Kubernetes Engine"]',
   2, '[2]', 'single',
   '{"asked": "オンプレの Spark / Hadoop クラスターを、既存プログラムをほぼ書き換えずに、運用の手間を減らしてクラウドへ移す方法を選べるか。", "point": "要件に Spark や Hadoop の名前が出てきて「そのまま動かしたい」なら Cloud Dataproc。", "kid": "Hadoop や Spark は「大量のデータを何百台もの機械で手分けして処理する道具一式」のこと。今までは、その何百台を自社で組み立てて面倒を見ていた。Cloud Dataproc は、その一式が最初から組み上がった状態で借りられるサービスで、今まで書いたプログラムはそのまま動く。", "eg": "引っ越しに似ている。同じ工具で同じ作業を続けたいのに、工具ごと別ブランドの新品に買い替えろと言われたら手順を覚え直しになる。Dataproc は「工具はそのまま、作業場だけ広くてきれいな貸し工房に移る」という話。", "terms": [["Cloud Dataproc", "Spark / Hadoop / Hive / Presto をそのまま動かせる Google のマネージドサービス。クラスターの作成が数分で済み、使い終わったら消せる。"], ["Apache Spark / Hadoop", "大量データを多数のマシンに分けて処理するオープンソースの仕組み。企業が長年書きためたジョブ資産がここに乗っている。"], ["マネージドサービス", "サーバーの構築・故障対応・アップデートをクラウド側が肩代わりしてくれる形態。"], ["リフト＆シフト", "作りを変えずにそのままクラウドへ載せ替える移行方式。まずここから始めるのが定石。"]], "think": "選択肢を「既存のジョブが書き換え無しで動くか」の一点でふるいにかける。Compute Engine は箱（仮想マシン）を貸すだけなので、Hadoop の組み立てと子守りは自分の仕事のまま残り、移行しても運用の手間が減らない。BigQuery は SQL を投げて分析する基盤で、Spark のジョブは SQL ではないから書き直しが要る。GKE はコンテナを動かす土台で、Hadoop をその上に載せる構成自体を自分で設計することになり、手間はむしろ増える。残る Cloud Dataproc だけが、既存ジョブをそのまま受け取り、クラスターの面倒を代わりに見てくれる。", "vs": "BigQuery と迷いやすい。どちらも「大量データを速く処理」だが入口が違う。手元にあるのが SQL なら BigQuery、Spark / Hadoop のジョブなら Dataproc。", "why_asked": "移行の設問には「運用負荷を抑え」「既存資産の変更を最小限に」という 2 語がほぼ必ず添えられる。ここを読み飛ばして「新しくて高機能なほう」を選ぶと BigQuery を掴む。試験は最新サービスの知識ではなく、要件文の制約を拾えるかを見ている。", "usecase": "夜間バッチの Spark ジョブを抱えた企業がクラウドへ移る初手。まず Dataproc でそのまま動かして安定させ、余裕ができてから一部を BigQuery や Dataflow に作り替える二段構えが実務の定番。", "opt": ["Compute Engine は仮想マシンを貸すだけ。Hadoop の構築・パッチ・故障対応が今まで通り自分の仕事として残るので、運用負荷を抑えたいという要件を満たさない。", "BigQuery はサーバーレスのデータウェアハウス。SQL での分析には非常に強いが、Spark / Hadoop のジョブをそのまま実行する場所ではないので、既存資産の書き換えが発生する。", "正解。Spark / Hadoop / Hive / Presto をそのまま実行できるフルマネージドサービス。既存プログラムをほぼ変えずに移せて、クラスターの作成やスケーリングは自動化されている。", "GKE はコンテナの実行基盤。Hadoop を載せること自体は不可能ではないが、構成と運用を自分で設計する分だけ手間が増え、要件と逆方向に進む。"]}'),

  ('gcp-pca-g-q4', '設計・計画',
   'あなたは農業IoTソリューションを提供する企業のデータエンジニアです。各地の農場から送られてくるセンサー情報は、長年オンプレミス環境のデータベースで管理されてきましたが、保守が不十分でデータの整合性が損なわれつつあります。分析レポートの信頼性を高めるため、Googleのベストプラクティスに従って、データ内の異常を効率的に検知・修正する仕組みを構築したいと考えています。要件を達成するためにあなたがすべきことは何ですか？',
   NULL::text,
   '["Cloud Storageにデータファイルをアップロードし、Cloud Dataprepを利用してデータの探索とクレンジングを実行する。", "Cloud Dataprepをオンプレミス環境のシステムに直接接続し、DataprepのUIからデータの探索とクリーニングを行う。", "オンプレミスのソースシステムにCloud Datalabを接続し、Datalabのノートブック環境でデータの調査とクリーニングを行う。", "Cloud Storageへファイルを転送した後、Cloud Datalabを用いてデータのプロファイリングとクレンジングを実施する。"]',
   0, '[0]', 'single',
   '{"asked": "汚れたセンサーデータを、コードを書かずに効率よく調べて直す仕組みとして、どのサービスをどこに置くか。", "point": "「データの中身を見て、異常を見つけて直す」を画面操作でやりたいなら Cloud Dataprep。置き場所は Cloud Storage。", "kid": "データクレンジングとは「表の中の、抜け・重複・単位違い・変な外れ値を見つけて直す作業」のこと。Dataprep はその作業を、表計算ソフトのように画面上で確かめながら進められる道具。Datalab はノート（Jupyter）にコードを書いて分析する道具で、同じことはできるが自分で書く量が多い。", "eg": "健康診断に例えると、Dataprep は数値の一覧と分布のグラフを自動で出してくれる検査結果票。Datalab は測定器を渡されて、自分で測るところから始める形。", "terms": [["Cloud Dataprep", "データの分布を自動で可視化し、変換ルールを画面操作で作れるサーバーレスのデータ準備サービス。"], ["Cloud Storage", "あらゆるファイルを置ける Google のオブジェクトストレージ。分析前のデータの一時置き場としてほぼ必ず経由する。"], ["データクレンジング", "欠損・重複・表記ゆれ・外れ値を見つけて直し、分析に耐える品質にする作業。"], ["Cloud Datalab", "Jupyter ノートブック環境。コードを書いて自由に分析できるが、その分だけ手を動かす量が増える。"]], "think": "二軸で切る。ひとつは「データをどこに置くか」。Dataprep も Datalab も Google Cloud 上のデータ（Cloud Storage や BigQuery）を読むのが前提なので、オンプレのシステムに直接つなぐ案はまず落ちる。もうひとつは「効率よく」。設問は仕組みの構築を求めており、都度コードを書く Datalab より、探索と変換を画面で完結できる Dataprep のほうが要件に沿う。この二軸を通すと、Cloud Storage に置いて Dataprep で処理する案だけが残る。", "vs": "Dataprep と Datalab の役割の差が本丸。Dataprep は「データを整える」専用でノーコード。Datalab は「データを調べて考える」ための汎用ノートブックでコードが要る。設問に「効率的に」「ベストプラクティスに従って」とあれば専用ツールを採る。", "why_asked": "Google Cloud のデータ系サービスは名前が似ていて役割が違う（Dataproc / Dataprep / Dataflow / Datalab）。試験はこの並びを混ぜて出す。名前ではなく「誰が何を書くか（コードか画面か）」「どこのデータを読むか」で切り分けられるかを見ている。", "usecase": "外部から受け取った CSV や、長年放置された基幹 DB の吐き出しを分析基盤に載せる前の前処理。まず Cloud Storage に置き、Dataprep で分布を眺めて異常を見つけ、変換ルールを固めてから定期実行に載せる。", "opt": ["正解。Cloud Storage に置くことで Dataprep がそのまま読める。あとは画面上でデータの分布を見ながら異常を特定し、変換ルールを適用して整えられる。", "Dataprep が読むのは Cloud Storage や BigQuery 上のデータ。オンプレミス環境に直接つないで処理する構成は想定されていない。", "Datalab は Jupyter ベースのノートブック環境で、自動的な探索や大規模なクレンジングに特化してはいない。加えてオンプレ直結という置き場所も適切でない。", "Cloud Storage へ転送するところまでは正しいが、Datalab はコードを書いて分析するツール。効率化が目的なら専用の Dataprep を採る。"]}'),

  ('gcp-pca-g-q6', '信頼性の確保',
   'あなたは教育系eラーニングプラットフォームを運営する企業のクラウドアーキテクトです。学習管理システムのデータベースとして、Google Cloud 上に Microsoft SQL Server を構築するプロジェクトを任されました。経営陣からは、特定の GCP リージョン内の一つのゾーンで障害が発生しても、サービスが停止せず継続できる構成にすることを強く求められています。要件を達成するためにあなたがすべきことは何ですか？',
   NULL::text,
   '["リージョン構成を選択して、Cloud Spanner インスタンスをプロビジョニングする。", "Cloud SQL インスタンスを作成し、高可用性（HA）構成を有効にする。", "Compute Engine インスタンス上に SQL Server を構築し、Windows Server Failover Clustering と Always On 可用性グループを用いて、ノードを別々のサブネットに配置する。", "Windows Server Failover Clustering を利用した Always On 可用性グループを構成し、Compute Engine の各ノードを異なるゾーンに展開する。"]',
   1, '[1]', 'single',
   '{"asked": "GCP 上の SQL Server で、リージョン内の 1 ゾーンが落ちてもサービスを止めない構成の選び方。", "point": "「ゾーン障害に耐える」と「SQL Server」が並んだら、まず Cloud SQL の高可用性（HA）構成。自前構築はマネージドで足りないときだけ。", "kid": "ゾーンは、同じ地域の中にある独立した建物だと思えばいい。1 つの建物が停電しても、別の建物に同じデータベースの控えが動いていれば、そちらへ切り替えてサービスを続けられる。Cloud SQL の HA は、この「別の建物の控え」と「自動切り替え」を、設定ひとつで用意してくれる。", "eg": "店の非常用発電機に似ている。停電したら自動で発電機に切り替わる仕組みを、自分で配線するか（Compute Engine で自前構築）、最初から組み込まれた建物を借りるか（Cloud SQL の HA）の違い。", "terms": [["Cloud SQL", "MySQL / PostgreSQL / SQL Server に対応した Google のフルマネージドなリレーショナルデータベース。"], ["高可用性（HA）構成", "リージョン内の別ゾーンに待機系を自動で置き、障害時に自動で切り替える設定。"], ["フェイルオーバー", "本番系が倒れたとき、待機系へ処理を引き継ぐ動作。"], ["Always On 可用性グループ", "SQL Server 自身が持つ冗長化機能。Compute Engine 上で自前構築するときに使うが、設計も運用も自分持ちになる。"]], "think": "まず「SQL Server である」という制約で切る。Cloud Spanner は Google 独自のデータベースで SQL Server の代わりにはならないので、可用性がいくら高くても要件を満たさない。残るのは、Cloud SQL のマネージドな HA か、Compute Engine 上で Windows Server Failover Clustering と Always On を自前で組むか。自前構築はクラスターの設計・監視・パッチをすべて自分で背負うことになる。同じゾーン冗長がマネージドで手に入るなら、そちらを採るのがクラウドの設計原則。よって Cloud SQL の HA を有効にする案が最適になる。", "vs": "「技術的にできる」と「設計として選ぶべき」は別。Compute Engine 上の Always On はできるが、運用の重さの分だけ評価が下がる。逆に SQL Server 互換が不要な新規設計なら Spanner が候補に入る、という順で条件を見る。", "why_asked": "「できる案」を複数並べ、要件（互換性・運用負荷）でどれを採るかを問うのが PCA の典型。動くかどうかだけで選ぶと自前構築を掴む。", "usecase": "既存の SQL Server 資産をクラウドへ移すとき。まず Cloud SQL for SQL Server で足りるかを確認し、特殊な機能で足りない場合にだけ Compute Engine 上の自前クラスターへ落とす。", "opt": ["Cloud Spanner は可用性こそ高いが、SQL Server とは互換性のない別製品。移行先のデータベースとして成り立たない。", "正解。HA を有効にするとリージョン内の別ゾーンに待機系が自動で配置され、ゾーン障害時に自動でフェイルオーバーする。運用も Google 側が持つ。", "自前で WSFC と Always On を組む構成は管理負荷が高い。さらにノードを別サブネットに分けただけでは、ゾーン障害への対策として不十分な場合がある。", "別ゾーンに分ければ技術的にはゾーン障害に耐えられるが、クラスターの構築と運用をすべて自分で背負うことになる。同じことがマネージドで済むなら Cloud SQL を採る。"]}'),

  ('gcp-pca-g-q7', 'インフラのプロビジョニングと管理',
   'あなたは人事系SaaSを提供する企業のクラウドアーキテクトです。US-Centralリージョンで稼働している本番用Linux仮想マシンの複製を作成する計画を立てています。本番環境で構成変更があった際、コピーの管理や入れ替えを柔軟に行えるようにし、最終的にはUS-Eastリージョンにある別プロジェクトで新しいインスタンスとしてデプロイする必要があります。要件を達成するためにあなたがすべきことは何ですか？',
   NULL::text,
   '["Linuxのddコマンドを用いてルートディスクからイメージファイルを抽出し、そのファイルを元にUS-Eastリージョンで新しい仮想マシンインスタンスを構築します。", "ルートディスクのスナップショットを保存し、US-Eastリージョンで新しい仮想マシンを立ち上げる際に、そのスナップショットをブートディスクとして直接選択します。", "Linuxのddコマンドとnetcatコマンドを併用し、ルートディスクの全内容をUS-Eastリージョンに用意した新しい仮想マシンインスタンスへネットワーク経由でストリーミング転送して同期します。", "ルートディスクのスナップショットを生成し、そのスナップショットからGoogle Cloud Storage上にイメージファイルを作成します。次に、そのイメージファイルをルートディスクとして使用し、US-Eastリージョンの別プロジェクトに新しい仮想マシンインスタンスをプロビジョニングします。"]',
   3, '[3]', 'single',
   '{"asked": "本番 VM の複製を、別リージョンの別プロジェクトへ配れる形で作る手順。", "point": "VM の複製を「別プロジェクトへ配る・版を管理する」ならカスタムイメージ。スナップショットは自分用のバックアップ、イメージは配れる型。", "kid": "スナップショットは「ディスクをその時点で丸ごと写した控え」。カスタムイメージは、その控えから作った「新しい VM を何台でも起こせる型（テンプレート）」。型にしておくと、別のプロジェクトの人に渡したり、第1版・第2版と版を分けて管理したりできる。", "eg": "料理で言えば、スナップショットは「いま作った鍋の中身をそのまま冷凍したもの」、カスタムイメージは「誰でも同じ味を再現できるレシピ」。他店舗に配って展開したいならレシピのほうを渡す。", "terms": [["スナップショット", "永続ディスクのある時点の状態を保存したバックアップ。増分で保存され、復元や複製の起点になる。"], ["カスタムイメージ", "ブートディスクの中身を型として保存したもの。プロジェクトをまたいで共有でき、これを元に新しい VM を何台でも作れる。"], ["Cloud Storage", "イメージの実体の保存先。リージョンをまたいだ受け渡しの土台になる。"], ["プロジェクト", "Google Cloud の課金と権限の入れ物。境界を越えてリソースを渡すには、共有できる形にする必要がある。"]], "think": "要件は 3 つある。別リージョンへ運ぶこと、別プロジェクトへ渡すこと、そして構成変更のときに入れ替えを柔軟にできること。効いてくるのは 3 つ目。単なるバックアップからの復元では「版を持って入れ替える」運用がやりにくい。カスタムイメージにしておけば、版ごとにイメージを持ち、新しい VM はどの版から起こすかを選ぶだけで済む。またイメージは Cloud Storage を土台にプロジェクト間で共有できるので、境界越えの要件も同時に満たす。よってスナップショットを取り、そこからイメージを作り、そのイメージから別プロジェクトで VM を起こす流れになる。", "vs": "dd を使う案が 2 つ紛れているが、どちらも OS の中から生のディスクをコピーする発想。クラウドが用意した整合性のある仕組みを使わず、転送中の破損や書き込み中データの不整合を自分で背負うことになる。", "why_asked": "「スナップショットから直接 VM を起こせる」のは事実なので、そこで止まると引っかかる。設問が求めているのは一度きりの複製ではなく、繰り返し配って入れ替える運用。要件文の「柔軟に」「最終的には別プロジェクトへ」を拾えるかが分かれ目。", "usecase": "検証済みのゴールデンイメージを作って各チームのプロジェクトへ配る運用。セキュリティ設定や監視エージェントを入れ込んだ状態を型にしておけば、どのチームが起こしても同じ構成になる。", "opt": ["dd による手動のイメージ抽出は、クラウドが用意した整合性のあるスナップショット機能を使っていない。版の管理も共有もしにくい。", "スナップショットから VM を起こすこと自体は可能だが、別プロジェクトへ配ったり版を管理したりする運用には、カスタムイメージにしておくほうが適する。", "dd と netcat でディスクを流し込む方法は、転送中の破損やセキュリティの面で推奨されず、手順としても非効率。", "正解。スナップショットからカスタムイメージを作れば、プロジェクトの境界を越えて配布でき、版を持って入れ替える運用もできる。そのイメージを元に別リージョン・別プロジェクトで VM を起こす。"]}'),

  ('gcp-pca-g-q11', '設計・計画',
   'あなたはラストワンマイルを担う物流企業のクラウドアーキテクトです。社内の開発チームが、Go 1.12を用いてHTTP(S)ベースのAPIを開発し、クラウド上へ展開する計画を立てており、あなたに助言を求めています。このAPIは配送依頼の急激な変動によりトラフィックの予測が非常に難しく、負荷のピーク時でも高い信頼性を維持することが求められています。また、チームはインフラ管理に費やす運用上のオーバーヘッドを可能な限り抑えたいと考えています。要件を達成するためにあなたがすべきことは何ですか？',
   NULL::text,
   '["Compute Engineのインスタンスを利用し、マネージドインスタンスグループ（MIG）を構成してデプロイする。", "Google App Engine Standard Environmentを採用してアプリケーションを構築する。", "カスタムランタイムを構成し、App Engine Flexible Environment向けにアプリケーションを開発する。", "アプリケーションをコンテナ化し、Google Kubernetes Engine（GKE）へデプロイする運用を選択する。"]',
   1, '[1]', 'single',
   '{"asked": "Go 1.12 の HTTP API を、トラフィックが読めない前提で、運用の手間を最小にして動かす基盤の選択。", "point": "「運用の手間を最小」と「急な増減にすぐ追従」が並んだらサーバーレス。言語が対応リストにあるなら App Engine 標準環境。", "kid": "App Engine 標準環境は「言語で書いたコードを置くだけで動く」サーバーレスの実行場所。サーバーの台数も OS の更新も気にしなくていい。急にアクセスが増えれば数秒で台数が増え、誰も来なければ 0 台まで減って課金も止まる。", "eg": "電気と自家発電の違い。VM を並べるのは自家発電機を何台か常に回しておく形で、増やすには機械を追加して起動を待つ。サーバーレスはコンセントに挿すだけで、使った分だけ払う。", "terms": [["App Engine 標準環境", "対応言語のコードをそのまま載せるサーバーレス実行環境。起動が速く、0 台まで縮小できる。"], ["App Engine フレキシブル環境", "コンテナとして VM 上で動く方式。任意のランタイムを使えるが起動が遅く、最低 1 台は動き続ける。"], ["マネージドインスタンスグループ（MIG）", "同じ構成の VM を束ねて自動増減させる仕組み。OS の管理は利用者側に残る。"], ["運用上のオーバーヘッド", "OS のパッチ、監視、容量計画など、アプリ本体以外に人手が取られる部分。"]], "think": "「運用の手間を最小に」という一句で、管理対象がどれだけ残るかの順に並べる。Compute Engine の MIG は OS のパッチも監視も自分持ちで、一番重い。GKE はクラスターとノードの面倒を見る必要があり、次に重い。App Engine フレキシブル環境はコンテナを VM 上で動かす方式なので起動に分単位かかり、予測できない急増に追従しきれず、最低 1 台は動き続ける。App Engine 標準環境は Go 1.12 を直接サポートしていて、急増に秒単位で追従し、アクセスがなければ 0 台まで縮む。「運用最小」と「急増に強い」を同時に満たすのはここだけ。", "vs": "App Engine の標準環境とフレキシブル環境の差が本丸。標準は「対応言語なら速くて安い」、フレキシブルは「何でも動くが遅くて最低 1 台」。設問に急激な変動と運用最小が並んでいたら標準を採る。", "why_asked": "「App Engine」とだけ覚えていると、標準とフレキシブルのどちらかで迷う。試験はこの 2 つを必ず並べて出す。判断軸は起動速度と、0 台まで縮むかどうか。", "usecase": "アクセスが読めない社外向け API や Webhook の受け口。人手をかけずに立ち上げ、当たれば勝手にスケールし、外れても課金がほぼ発生しない。", "opt": ["MIG は自動増減こそするが、OS の管理やパッチ適用が利用者側に残る。運用のオーバーヘッドを最小にという要件から外れる。", "正解。Go 1.12 を直接サポートし、急なトラフィック増に高速にスケールする。アクセスがなければ 0 インスタンスまで縮んでコストも抑えられる。", "フレキシブル環境はインスタンスの起動とスケーリングが標準環境より遅く、予測困難な急変動への追従に向かない。", "GKE はクラスターとノードの管理が必要で、運用上のオーバーヘッドを最小にするという要件に合わない。"]}'),

  ('gcp-pca-g-q15', '信頼性の確保',
   'あなたはモバイルゲーム開発会社のSREです。自社のゲームアプリケーションをGoogle Kubernetes Engine (GKE) 上で運用しており、Cloud SQLプロキシをサイドカーとして配置してCloud SQLデータベースへの接続を確立しています。現在、アプリケーション層でデータベースへの接続エラーが多発しているとの報告を受けました。組織の運用ガイドラインでは、障害発生時に原因の事後検証（ポストモーテム）を必ず実施することが定められています。要件を達成するためにあなたがすべきことは何ですか？',
   NULL::text,
   '["Cloud SQL プロキシコンテナが認証に使用しているサービスアカウントに対し、Cloud Build 編集者のロールが正しく割り当てられているかを確認する。", "Google Cloud コンソールの Cloud Logging 画面にアクセスし、GKE のワークロードおよび Cloud SQL インスタンスに関連するログを詳細に調査する。", "Google Cloud コンソールで Cloud SQL の管理画面を開き、最新のバックアップからの復元を行った後、kubectl コマンドを用いて全 Pod のローリングアップデートまたは再起動を実施する。", "gcloud sql instances restart コマンドを実行し、対象のデータベースインスタンスを強制的に再起動させる。"]',
   1, '[1]', 'single',
   '{"asked": "GKE から Cloud SQL への接続エラーについて、根本原因を突き止めるためにまず何をするか。", "point": "設問に「原因究明」「ポストモーテム」が出てきたら、復旧アクションではなくログを見る。", "kid": "ポストモーテムとは「障害の後、何が起きたかを振り返って再発を防ぐための検証」のこと。検証には記録が要る。再起動や復元をすると状態が上書きされ、記録が読み取れなくなることすらある。だからまずログを読む。", "eg": "事故の原因調査で、ドライブレコーダーを見る前に車を修理して洗車してしまうようなもの。直すのは記録を取ってから。", "terms": [["Cloud Logging", "Google Cloud 上の各リソースが出すログを集めて検索・分析できる統合サービス。"], ["Cloud SQL プロキシ", "アプリと Cloud SQL の間に立ち、認証と暗号化を担うツール。接続エラーの原因はここのログに出ることが多い。"], ["サイドカー構成", "本体のコンテナと同じ Pod に補助役のコンテナを並べて動かす設計。プロキシはこの形で置くのが定番。"], ["ポストモーテム", "障害後に原因と対応を振り返り、再発防止策をまとめる事後検証。"]], "think": "取るべき行動を「原因が分かるか」「状態を壊さないか」の二軸で見る。バックアップからの復元と Pod の再起動は、症状は消えるかもしれないが、そのとき何が起きていたかの手がかりも一緒に消える。インスタンスの強制再起動はさらに踏み込んだ操作で、サービスを止めるうえに原因は分からないまま。Cloud Build 編集者のロールを確認する案は、そもそも接続に必要な権限が別のもの（Cloud SQL クライアント）なので、調べる対象を取り違えている。残る Cloud Logging の調査だけが、アプリ・プロキシ・Cloud SQL 本体のログを時系列で並べ、いつどのエラーが出たかを示せる。", "vs": "「対処」と「原因究明」を混ぜない。運用ガイドラインがポストモーテムを義務づけている以上、先に記録を取ることが手順として上位に来る。", "why_asked": "現場では復旧を急ぎたくなる。試験はその反射を突いて、復旧アクションを魅力的な選択肢として並べる。SRE の作法では、記録の保全が復旧と並ぶ優先事項だと知っているかを見ている。", "usecase": "接続エラーの調査では、アプリのログ（タイムアウトか認証拒否か）、プロキシのログ（トークン取得の失敗）、Cloud SQL 側のログ（接続数の上限）を突き合わせる。どこで詰まったかで打ち手がまるで変わる。", "opt": ["Cloud SQL への接続に必要なのは Cloud SQL クライアントのロール。Cloud Build 編集者は無関係で、調べる対象を取り違えている。", "正解。アプリ、サイドカーのプロキシ、Cloud SQL インスタンスのログを時系列で追える。いつどんなエラーが出たかが分かり、ポストモーテムの材料になる。", "復元と再起動は一時的に症状を消すかもしれないが、根本原因の特定にはつながらず、手がかりも失われる。", "強制再起動はサービス中断を招くうえ、原因は分からないまま。ログ調査より先にやるべき操作ではない。"]}'),

  ('gcp-pca-g-q16', 'インフラのプロビジョニングと管理',
   'あなたは医療機関のクラウドアーキテクトです。自社の電子カルテシステムに関連する複数のワークロードをCompute Engineインスタンス上で稼働させています。これらのアプリケーションが、オンプレミス環境に設置されたデータベースと内部IPアドレスを通じて通信し、膨大な医療データを扱うための高いスループットと最小限のネットワーク遅延を実現しなければなりません。要件を達成するためにあなたがすべきことは何ですか？',
   NULL::text,
   '["マネージドサービスであるCloud VPNをデプロイし、オンプレミス拠点との間に暗号化されたVPN接続をセットアップする。", "自社のデータセンターとGoogle Cloudのネットワーク間において、Cloud Dedicated Interconnectを用いた物理的な接続を確立する。", "OpenVPNのソフトウェアを導入し、オンプレミス環境とGoogle Cloudを繋ぐVPNトンネルを構築する。", "Google Cloudとオンプレミス拠点の間で、ダイレクト ピアリングによる接続設定を行う。"]',
   1, '[1]', 'single',
   '{"asked": "オンプレミスの DB と内部 IP で結び、高スループットかつ最小遅延を求められたときの接続方式。", "point": "「高スループット」と「最小遅延」が並んだら、インターネット経由の VPN ではなく物理直結の Dedicated Interconnect。", "kid": "Cloud VPN は、インターネットという公道を、暗号化した箱に入れて荷物を運ぶ方式。混めば遅くなるし、到着時間も日によってぶれる。Dedicated Interconnect は自社と Google の間に専用の私道を引く方式で、公道の混雑と無関係に安定して速い。", "eg": "宅配便と専用トラック便の違い。普段は宅配便で足りるが、毎日大量に運ぶうえ時間厳守なら、自社専用の便を確保する。", "terms": [["Dedicated Interconnect", "自社データセンターと Google のネットワークを物理回線で直結する接続。大きな帯域と低遅延、高い SLA が得られる。"], ["Cloud VPN", "インターネット越しに暗号化トンネルを張るマネージド VPN。手軽だが速度と遅延はインターネット任せ。"], ["ダイレクト ピアリング", "Google の公開サービスへの経路を最適化する接続。VPC 内部 IP へ届くものではない。"], ["スループットと遅延", "単位時間に運べる量と、届くまでの時間。大量データにはスループット、対話的な処理には遅延が効く。"]], "think": "要件が 2 つ重なっている点に注目する。内部 IP で通信すること、そして高スループットと最小遅延であること。ダイレクト ピアリングは Google の公開サービス向けの経路なので、VPC の内部 IP には届かず、前者で落ちる。Cloud VPN と OpenVPN はどちらもインターネットを経由するため、経路の混雑に性能が左右され、後者を安定して満たせない。物理回線で Google のネットワークに直結する Dedicated Interconnect だけが、内部 IP への到達と、インターネットに依存しない安定性を同時に満たす。", "vs": "Cloud VPN と Interconnect は「どちらもオンプレとつなぐ」が、通る道が違う。暗号化の有無ではなく、公道か私道かで選ぶ。要件に性能が書かれていなければ、安くて早く始められる VPN が正解になることもある。", "why_asked": "医療や金融のシナリオでは「膨大なデータ」「最小の遅延」という表現が性能要件の合図として置かれる。この合図を読めば VPN 系はすべて落ちる。逆に合図がなければ VPN で足りる、という読み分けを問うている。", "usecase": "オンプレの基幹 DB を残したままアプリだけクラウドへ出すハイブリッド構成。日次で数 TB を動かす、あるいは画像を対話的に読み出すような用途で Interconnect が要る。", "opt": ["Cloud VPN はパブリックインターネットを経由するため、Dedicated Interconnect ほどの性能や安定性は出せない。", "正解。自社データセンターと Google のネットワークを物理的に直結する。インターネットを経由しないので、大容量転送に必要な帯域と低遅延を安定して得られる。", "OpenVPN もインターネット経由のソフトウェア VPN。帯域が制限され、高スループット・低遅延の要件を満たしにくい。", "ダイレクト ピアリングは Google の公開サービスへのアクセス向け。VPC 内部 IP への直接接続や高い SLA を保証するものではない。"]}'),

  ('gcp-pca-g-q18', 'プロセスの分析と最適化',
   'Eコマースプラットフォームを運営する「Global ShopStream」では、クラウド費用の見直しを行っています。最近のコスト監査において、商品プロモーション動画のエンコーディングやトランスコーディング処理用に大量のCompute Engineインスタンスが稼働し続けていることが問題視されました。これらのリソースの中には、処理完了後も解放されずに残存している「ゾンビインスタンス」が多数含まれていると推測されています。インフラ担当者として、不要なコストを削減するために、アイドル状態にあるVMインスタンスを迅速にリストアップしなければなりません。最適な方法はどれですか？',
   NULL::text,
   '["`gcloud compute instances list` を実行し、`idle: true` というラベルが設定されているインスタンスを検索して特定する。", "Google Cloudの `gcloud recommender` コマンドを活用して、利用率が低くアイドル状態とみなされる仮想マシンインスタンスのリストを生成する。", "Google Cloud コンソールにアクセスし、マネージド インスタンス グループ（MIG）内でヘルスチェックの応答が停止している Compute Engine インスタンスを手動で確認する。", "対象となるすべての Compute Engine インスタンスに個別にリモートログインし、CPU、メモリ、ディスク、ネットワークの稼働統計を収集して個別に判断する。"]',
   1, '[1]', 'single',
   '{"asked": "使われていない VM を、素早く一覧にして洗い出す方法。", "point": "「使っていないリソースを見つけたい」なら Recommender。手作業で調べる案はすべて落ちる。", "kid": "Recommender は、Google Cloud が過去の使用状況を自動で分析して「これ、要らないのでは」と教えてくれる仕組み。VM の CPU やネットワークの使用量を 14 日分見て、ほとんど動いていないものを候補として挙げてくれる。", "eg": "電力会社が「この部屋、1 か月ずっと待機電力しか流れていません」と教えてくれるようなもの。全部屋を自分で見て回る必要がない。", "terms": [["Recommender", "使用状況を分析して、コスト削減・セキュリティ・性能の改善案を自動で提示する Google Cloud のサービス。"], ["アイドル VM の推奨事項", "過去 14 日のメトリクスから、ほぼ使われていない VM を検出して停止や削除を提案する機能。"], ["Cloud Monitoring", "リソースの使用状況を継続的に集める監視サービス。Recommender の判断材料はここから来る。"], ["ゾンビインスタンス", "処理が終わったのに消し忘れて課金だけ続いているインスタンス。コスト監査で必ず槍玉に挙がる。"]], "think": "「アイドルかどうか」は、その瞬間の状態ではなく一定期間の使用実績から判断するしかない。インスタンス一覧のコマンドは名前や状態を並べるだけで使用実績を見ていないし、idle というラベルが自動で付く仕組みも存在しない。MIG のヘルスチェックは「応答するか」を見るもので、応答していても CPU が遊んでいれば無駄なので、判断軸が違う。全台にログインして統計を取る案は、実績を見ている点では正しいが、台数が多いと現実的でない。過去 14 日の Monitoring メトリクスをもとに Google 側が判定してくれる Recommender を使えば、一括で機械的に取れる。", "vs": "「稼働しているか（ヘルスチェック）」と「役に立っているか（使用率）」は別。ゾンビインスタンスは、前者では健康、後者では無駄、という状態を指す。", "why_asked": "コスト最適化の設問には、手作業でもできる案が必ず並ぶ。試験は「できる／できない」ではなく「クラウドが用意した自動化を知っているか」を見ている。", "usecase": "四半期のコストレビュー。gcloud recommender でアイドル VM・使われていない永続ディスク・過大なマシンタイプの推奨をまとめて取り、担当チームに配って棚卸しする。", "opt": ["インスタンス一覧はリソースの基本情報を並べるだけで、使用実績を見ていない。idle: true というラベルが自動で付く仕組みも存在しない。", "正解。過去 14 日の Cloud Monitoring メトリクスをもとに、使用率の低い VM を Google 側が検出してくれる。コマンドで一括取得できるので棚卸しが速い。", "ヘルスチェックは応答しているかを見る仕組み。応答していても遊んでいれば無駄なので、利用効率の判断には使えない。", "全台に個別ログインして統計を集めるのは台数が増えるほど非現実的で、クラウドの自動分析を活用できていない。"]}'),

  ('gcp-pca-g-q21', 'セキュリティとコンプライアンス',
   '再生可能エネルギー事業を展開する Solaris Green Energy Solutions のプロジェクトにおいて、Google Cloud 上にワークロードを安全に展開するための技術アーキテクチャを設計することになりました。この際、セキュリティ基準を満たし、検証済みのコンテナイメージのみが Google Cloud のサービスを通じてデプロイされる体制を整える必要があります。この要件を実現するための適切な手法を 2 つ選んでください。',
   NULL::text,
   '["特定の信頼されたサービスアカウントのみがレジストリからイメージを取得してデプロイできるよう、Container Registry のアクセス権限を制限する構成にする。", "Jenkins をプラットフォームとして構成し、CI/CD ワークフローの一環で Kritis を利用してコンテナに対する暗号署名を実行する。", "Google Kubernetes Engine (GKE) で Binary Authorization を有効化し、CI/CD パイプラインのフロー内で承認されたコンテナに対して署名を行うプロセスを組み込む。", "Container Registry において脆弱性スキャン機能を構成し、デプロイが実行される前にイメージにセキュリティ上の欠陥がないか自動的に検証する仕組みを導入する。"]',
   2, '[2, 3]', 'multi',
   '{"asked": "検証済みのコンテナイメージだけがデプロイされる体制を作るための、2 つの施策。", "point": "「中身が安全か」は脆弱性スキャン、「信頼できる経路を通ったか」は Binary Authorization。この 2 枚で挟む。", "kid": "コンテナイメージは、アプリを丸ごと詰めた箱のこと。中に古くて穴のあるライブラリが入っていないかを調べるのが脆弱性スキャン。ちゃんとした手順（テストや承認）を通った箱にだけ封印（署名）を押し、封印のない箱はクラスターに入れないのが Binary Authorization。", "eg": "空港に例えると、脆弱性スキャンは手荷物の X 線検査（中身に危険物がないか）、Binary Authorization は搭乗券とパスポートの照合（正規の手続きを踏んだ人か）。どちらか片方だけでは、通してはいけないものが通る。", "terms": [["脆弱性スキャン", "イメージ内のパッケージに既知の脆弱性がないかを自動検査する機能。レジストリ側で有効化する。"], ["Binary Authorization", "署名のあるイメージだけを GKE などにデプロイさせる、デプロイ時の関門。"], ["ソフトウェアサプライチェーン", "コードからビルド、レジストリ、デプロイまでの一連の経路。どこか一箇所でも汚染されると本番に届く。"], ["多層防御", "性質の違う対策を重ねて、1 つが破られても全体は守られるようにする考え方。"]], "think": "「検証済みのイメージだけがデプロイされる」を 2 段階に分けて読む。前段は、そもそも中身に既知の欠陥がないと確かめること。後段は、確かめたものだけが本番に届くよう強制すること。前段を担うのが脆弱性スキャン、後段を担うのが Binary Authorization で、この 2 つは互いの代わりにならない。スキャンだけでは、スキャンを通っていない野良イメージのデプロイを止められない。Binary Authorization だけでは、署名は付いていても中身が古くて穴だらけ、という状態を防げない。だから両方を選ぶ。", "vs": "アクセス権限の制限は「誰が取れるか」の話で、中身の安全性は保証しない。取得できる人を絞っても、その人が危険なイメージを置けば通ってしまう。", "why_asked": "セキュリティの複数選択では、どれも「良さそうな施策」が並ぶ。設問が言う「検証済み」を、検査と強制の 2 要素に分解できるかが分かれ目。", "usecase": "CI で作ったイメージをスキャンし、合格したものにだけ CI が署名を付ける。GKE 側は署名のないイメージを弾く。こうしておくと、開発者が手元から直接デプロイしても止まる。", "opt": ["アクセス権限の制限は不正な取得を防ぐ話で、イメージの中身が安全かどうかを保証するものではない。", "Jenkins と Kritis の組み合わせでも署名は実現できるが、GKE に統合されたマネージドの Binary Authorization ほど標準的な手法ではない。", "正解。署名の付いた承認済みイメージだけをデプロイさせる関門になり、検証を通っていないものが本番に届くのを防ぐ。", "正解。デプロイ前にイメージ内の既知の脆弱性を自動で検出し、危険な中身を持ち込ませない。"]}'),

  ('gcp-pca-g-q25', '設計・計画',
   'Aerial Race Circuit (ARC) のケーススタディに基づき、以下の課題を解決する構成を提案してください。ARCは、ストリーミング配信されるレースのテレメトリデータなどを保存するための、コスト効率に優れたストレージ基盤を必要としています。彼らは過去の全記録をアーカイブしつつ、前シーズンのデータに絞ってモデルの学習を実行することを想定しており、今後データ量や収集項目が大幅に増加することを見越した設計を求めています。CEOのJ.ファルコン氏が示すビジネス目標と要件を達成するために、どのデータソリューションを採用すべきですか？',
   NULL::text,
   '["ダウンタイムを発生させずにスキーマ更新が可能なCloud Spannerを導入し、シーズン情報を主キーに割り当ててレースデータの分散配置を行う。", "柔軟なスケーリングが可能なドキュメント指向のFirestoreを利用し、シーズンや大会イベントごとにコレクションを構成してレース情報を集約する。", "優れた拡張性と動的なスキーマ変更に対応できるBigQueryを採用し、シーズンごとのパーティショニングを適用してレースデータを効率的に管理する。", "ストレージ容量の自動拡張機能を備えたMySQL互換のCloud SQLを運用し、シーズンごとに個別のデータベースインスタンスを構築してデータを分離する。"]',
   2, '[2]', 'single',
   '{"asked": "増え続けるテレメトリを全部アーカイブしつつ、直近シーズンだけで学習を回す基盤の選定。", "point": "「全部貯めておいて、後から範囲を絞って分析・学習」なら BigQuery。範囲の絞り込みはパーティショニングで効かせる。", "kid": "テレメトリとは、機器から出続ける時系列の計測データのこと。BigQuery は膨大な量を貯めたまま、SQL で必要な分だけ取り出せる分析用のデータ置き場。パーティショニングは、テーブルをシーズンなどの区切りで棚分けしておく仕組みで、1 シーズンだけ読みたいときに他の棚を触らずに済むから速くて安い。", "eg": "倉庫の棚に年度ラベルを貼るようなもの。ラベルがなければ去年の書類を探すのに倉庫全体をひっくり返すことになるが、棚が分かれていれば該当の棚だけ開ければいい。", "terms": [["BigQuery", "サーバーレスのデータウェアハウス。極めて大量のデータを貯めたまま SQL で分析でき、機械学習にもそのまま渡せる。"], ["パーティショニング", "日付や指定した列でテーブルを分割し、クエリが読む範囲を絞る仕組み。速度とコストの両方に効く。"], ["テレメトリデータ", "センサーや機器から継続的に送られてくる時系列の計測データ。項目が後から増えやすい。"], ["スキーマ", "データの構造の定義。BigQuery は列の追加に対応しやすく、項目が増える前提の設計に向く。"]], "think": "要件は 3 つ。過去の全記録を貯め続けること、直近シーズンだけを取り出して学習に使えること、データ量も項目数もこれから大きく増えること。Cloud SQL は容量が増えるほど分析が苦しくなり、シーズンごとにインスタンスを分ける運用も増え続ける前提に耐えない。Firestore はアプリのリアルタイム同期に強いが、大量の時系列を横断して集計する用途ではない。Cloud Spanner は世界規模の強い整合性を要するトランザクション向けで、貯めて分析するだけの用途には高くつく。BigQuery は貯める量が増えても構造上の限界に当たりにくく、シーズンでパーティションを切れば読む範囲を絞れて、項目の追加にも対応できる。", "vs": "Spanner と BigQuery を「どちらも大規模」でまとめない。Spanner は書き込みの整合性を守るための道具、BigQuery は貯めたものを読み解くための道具。設問が分析と学習なら後者。", "why_asked": "ケーススタディでは「アーカイブ」と「分析・学習」が同じ文に並ぶ。この 2 つを 1 つのサービスで受けられるのがどれかを問うている。", "usecase": "IoT やゲームのテレメトリ基盤の定番。ストリーミングで BigQuery に入れ、日付やシーズンでパーティションを切り、直近だけを BigQuery ML や Vertex AI の学習に渡す。", "opt": ["Cloud Spanner は世界規模の強い整合性が要るトランザクション向け。貯めて分析するアーカイブ用途にはコスト効率が低い。", "Firestore はリアルタイム同期には優れるが、大規模なテレメトリの横断分析や、学習用のバッチ処理には向かない。", "正解。サーバーレスで拡張性が高く、シーズンごとにパーティションを切れば読む範囲を絞れる。項目の追加にも対応しやすい。", "Cloud SQL はシーズンごとにインスタンスを分ける運用になり、データ量が大幅に増える前提に対してスケーラビリティが足りない。"]}'),

  ('gcp-pca-g-q26', '信頼性の確保',
   'あなたは農業IoTスタートアップのクラウドアーキテクトです。各地の圃場に設置されたスマートセンサーから送信されるデータをCloud StorageにHTTP経由で保存するアプリケーションを構築しています。運用中、稀にHTTP 5xxエラーや、レート制限を示す429エラーによってリクエストが失敗する事象が確認されました。これらのエラーに適切に対処し、堅牢なデータ転送を実現するためにあなたがすべきことは何ですか？',
   NULL::text,
   '["https://status.cloud.google.com/feed.atom を継続的に監視し、Cloud Storageに関連するインシデントが報告されていない期間に限定してリクエストを送信する。", "指数的バックオフアルゴリズムを組み込んだリトライロジックをアプリケーション内に実装する。", "保存先となるCloud Storageバケットをマルチリージョン設定に変更し、地理的な冗長性を確保することでエラーを回避する。", "リクエストの処理能力を向上させるために、通信プロトコルをHTTPからgRPCへ移行する。"]',
   1, '[1]', 'single',
   '{"asked": "Cloud Storage への書き込みで時折出る 5xx と 429 に、アプリ側でどう備えるか。", "point": "5xx と 429 は「今は無理、あとでもう一度」の合図。指数バックオフ付きのリトライで受ける。", "kid": "429 は「リクエストが多すぎます」、5xx は「こちら側で一時的に失敗しました」という意味の返事。どちらも少し待てば通ることが多い。指数バックオフは、失敗のたびに待ち時間を倍々に伸ばして再送するやり方で、相手が混んでいるときに追い打ちをかけずに済む。", "eg": "電話がつながらないときに 1 秒おきにかけ直しても、回線を余計に混ませるだけ。1 秒、2 秒、4 秒と間隔を空けるほうが結果的に早くつながる。", "terms": [["指数バックオフ", "再試行の間隔を 1 秒、2 秒、4 秒と指数的に伸ばす方式。相手の回復を待ちつつ全体の負荷を下げる。"], ["ジッター", "バックオフの待ち時間に少しランダムをまぜる工夫。多数のクライアントが同じ瞬間に再送して波を作るのを防ぐ。"], ["HTTP 429", "短時間にリクエストを送りすぎたときに返る、レート制限の合図。"], ["HTTP 5xx", "サーバー側で一時的に処理できなかったことを示す応答。時間を置けば通ることが多い。"]], "think": "エラーの性質から打ち手を決める。5xx と 429 はどちらも恒久的な失敗ではなく、一時的な過負荷やバックエンドのスケーリング中に出るもの。つまり必要なのは「構成を変えること」ではなく「待ってからもう一度送ること」。ステータスページの監視は広域障害には効くが、個々のリクエストが弾かれた瞬間には間に合わない。マルチリージョン化は地理的な冗長性の話で、レート超過とは無関係。gRPC への移行は通信の効率を上げるかもしれないが、送りすぎたときに弾かれる事実は変わらない。残る指数バックオフだけが、エラーの性質に直接対応している。", "vs": "「可用性を上げる対策」と「一時エラーを受け流す対策」は別物。マルチリージョンは前者、リトライは後者。設問のエラーは後者にあたる。", "why_asked": "エラーコードを見て打ち手を決められるかを問うている。429 を「容量不足」と誤解すると、ストレージ構成をいじる案に引っかかる。", "usecase": "IoT のように多数のクライアントが同時に書き込む構成では必須。バックオフにジッターを足して、再送のタイミングが揃わないようにするのが実務の定番。", "opt": ["ステータスフィードの監視は広域障害の把握には有効だが、個々のリクエストで起きる一時エラーやレート制限をその場で回避する手段にはならない。", "正解。5xx や 429 は一時的な過負荷で出るものなので、再試行の間隔を段階的に延ばして相手の回復を待つのが正攻法。", "マルチリージョンは地理的な冗長性を高める機能。レート超過や一時的なサーバーエラーを直接解決するものではない。", "gRPC への移行は通信性能の改善にはなり得るが、送りすぎて弾かれることへの対策にはならず、再試行ロジックの代わりにもならない。"]}'),

  ('gcp-pca-g-q30', '設計・計画',
   'あなたは自動車部品製造業のクラウドアーキテクトです。現在、自社システムのGoogle Cloudへの移行プロジェクトをリードしていますが、既存のオンプレミス環境では高性能なSANストレージの維持・拡張に多額のコストがかかっていることが課題となっています。移行対象となるワークロードには、以下の異なる特性を持つデータが含まれています。

- 法的コンプライアンスのために保管が義務付けられている20TBのログアーカイブ
- 500GB分に相当する仮想マシンの起動用およびデータ用ボリュームとテンプレート
- 500GBの製品画像サムネイル
- ユーザーが数日間オフラインになった後でも作業を継続できる必要がある、200GBの顧客セッションステートデータ

これらのデータをコストパフォーマンスに優れた方法で各ストレージサービスへ割り当てるために、あなたがすべきことは何ですか？',
   NULL::text,
   '["セッションステートの永続化にCloud SQLでバックアップされたMemcacheを使用し、VMのボリュームにはローカルSSDで構成されたインスタンスを割り当て、ログとサムネイルの保管にはCloud Storageを選択します。", "顧客のセッションステートを保持するために、Cloud Datastoreをバックエンドに備えたMemcacheを導入し、ログアーカイブ、画像サムネイル、および仮想マシンのボリューム類については、ライフサイクル管理機能を有効にしたCloud Storageへ集約します。", "セッション管理のためにPersistent Disk（SSD）をバックエンドとするMemcacheを構成し、VMボリュームにはSSDベースのローカルインスタンスを組み合わせ、ログおよびサムネイルの保存にはCloud Storageを運用します。", "セッションデータの保存先としてローカルSSDを採用し、ログアーカイブやサムネイル、VMのブート/データボリュームの管理にはライフサイクルポリシーを適用したCloud Storageを利用します。"]',
   1, '[1]', 'single',
   '{"asked": "性質の違う 4 種類のデータを、コスト効率よく適切なストレージへ振り分ける組み合わせ。", "point": "「置きっぱなしの大きなデータ」はすべて Cloud Storage、「数日残す必要のあるセッション」はローカル SSD ではなく永続する保管場所で受ける。", "kid": "ローカル SSD は VM に直付けの高速ディスクだが、その VM が止まったり移動したりすると中身が消える。数日オフラインでも続きから使えるセッション情報を、消える場所に置いてはいけない。Memcache は速さのための一時置き場なので、その裏に消えない保管場所（Cloud Datastore）を置いて支える。", "eg": "レジの手元の現金トレイ（Memcache）と金庫（Cloud Datastore）の関係。手元は速いが夜には空にする。残しておくべきものは金庫に入れる。", "terms": [["Cloud Storage", "ログ・画像・VM のイメージまで置ける汎用のオブジェクトストレージ。ライフサイクル管理で自動的に安いクラスへ移したり削除したりできる。"], ["オブジェクトのライフサイクル管理", "経過日数などの条件でストレージクラスの変更や削除を自動化する機能。法定保存のログのコストを抑える主役。"], ["ローカル SSD", "VM に直付けの高速ディスク。速いが揮発性で、インスタンスが止まると内容が失われる。"], ["Cloud Datastore", "フルマネージドの NoSQL。セッションのような小さなデータを、消えない形で保持できる。"]], "think": "4 種類を性質で分ける。20TB のログアーカイブと 500GB のサムネイルは、書いたら基本は読むだけの大きなデータで、Cloud Storage が最も安く、ライフサイクル管理で古いものを自動的に安いクラスへ落とせる。VM のボリュームとテンプレートは、カスタムイメージとして Cloud Storage に置くのが素直。決め手になるのが残るセッションステートで、「数日間オフラインになった後でも作業を継続できる」という条件がある以上、消える場所には置けない。ローカル SSD は VM が止まれば失われるので不可。速さのために Memcache を使うのはよいが、その裏には永続する保管場所が要り、そこに適するのが Cloud Datastore。この組み合わせだけが 4 つすべての性質に合う。", "vs": "誤答はどれも「Memcache と何か」の形をしていて紛らわしい。見るべきは、裏に置く保管場所が永続かどうかと、VM ボリュームをローカル SSD に置いていないかの 2 点。", "why_asked": "複数の要件をまとめて満たす組み合わせを問う形式。1 箇所でも要件を壊していれば落ちる、という読み方ができるかを見ている。", "usecase": "オンプレの高価な SAN からの脱出。まずは性質ごとに置き場所を分け、大きくてめったに読まないデータをオブジェクトストレージへ寄せるのがコスト削減の効き所。", "opt": ["Cloud SQL を Memcache の裏に置く構成は一般的でなく、VM ボリュームにローカル SSD を使うと永続性とライフサイクル管理が損なわれる。", "正解。ログ・サムネイル・VM ボリュームはライフサイクル管理付きの Cloud Storage に寄せ、セッションは速い Memcache の裏に永続する Cloud Datastore を置いて支える。", "Persistent Disk を Memcache の裏に据える構成は標準的な設計ではなく、VM ボリュームへのローカル SSD 利用はホストのメンテナンス時にデータを失うおそれがある。", "ローカル SSD は揮発性で、インスタンスの停止や削除で内容が消える。数日にわたってセッションを維持する要件に合わない。"]}'),

  ('gcp-pca-g-q36', '設計・計画',
   'あなたは大手Eコマース企業のクラウドアーキテクトです。自社が運営する複数のオンラインショップから発生する膨大なクリックストリームデータを保存するための、最適なストレージソリューションの選定を任されました。このデータは独自の分析エンジンからストリーミングされており、平常時は毎分約6,000件ですが、セール時などのピーク時には秒間8,500件もの書き込みリクエストが発生します。蓄積されたデータは、将来的にデータサイエンティストやUXデザインチームが詳細な分析を行うために利用されます。要件を達成するために、どのストレージインフラを採用すべきですか？',
   NULL::text,
   '["Google Cloud SQL", "Google Cloud Spanner", "Google Cloud Storage", "Google Cloud Bigtable"]',
   3, '[3]', 'single',
   '{"asked": "秒間 8,500 件の書き込みが来るクリックストリームの保存先。", "point": "「秒間数千件以上の書き込み」と「時系列」と「後から分析」が揃ったら Cloud Bigtable。", "kid": "クリックストリームとは、利用者がサイト上でどこを押したかを 1 件ずつ記録し続けるデータのこと。1 件は小さいが数が桁違いに多い。Bigtable は、こうした小さな書き込みを大量に受け止めることに特化した NoSQL で、ノードを増やせば受け止められる量もほぼ比例して増える。", "eg": "駅の改札に似ている。1 人ずつの通過記録は小さいが、ラッシュ時は毎秒何千人も通る。窓口の係員が 1 人ずつ台帳に書く方式（リレーショナルデータベース）では詰まる。改札機を何台も並べる方式が Bigtable。", "terms": [["Cloud Bigtable", "低遅延かつ高スループットの NoSQL。時系列や IoT、広告のログなど、書き込みが極端に多い用途に使う。"], ["クリックストリームデータ", "利用者の操作を 1 件ずつ記録した行動ログ。行動分析やパーソナライズの元になる。"], ["水平スケーラビリティ", "ノードを足すほど処理能力が増える性質。書き込み量が読めない用途で効く。"], ["行キー設計", "Bigtable では行キーの付け方で負荷が偏る。時刻をそのまま先頭に置くと、書き込みが 1 ノードに集中してしまう。"]], "think": "求められている量から逆算する。秒間 8,500 件の書き込みは、リレーショナルデータベースを 1 台で受けるには重すぎる。Cloud SQL は台数を増やして書き込みを分散する仕組みを持たないので、ここで落ちる。Cloud Spanner は分散しつつ強い整合性も守れるが、その整合性のための仕組みにコストがかかる。クリックストリームは 1 件が独立した記録で、厳密なトランザクションを必要としないので過剰になる。Cloud Storage はファイル単位のオブジェクトストレージで、小さな書き込みを秒間数千件受ける用途ではない。Bigtable は分散を前提に、まさにこの形の負荷のために設計されている。", "vs": "Bigtable と BigQuery を混同しない。書き込みを受け止めて貯めるのが Bigtable、貯まったものを SQL で分析するのが BigQuery。分析だけを見て BigQuery を選ぶと、秒間 8,500 件の受け口という要件を落とす。", "why_asked": "この種の設問には必ず具体的な数値が置かれる。その数値が「リレーショナルでは無理」という合図になっている。数字を読み飛ばすと Spanner や Cloud SQL を選んでしまう。", "usecase": "広告配信、IoT センサー、ゲームのイベントログ。Bigtable で受けて、分析用に BigQuery へ流す二段構えが一般的。", "opt": ["Cloud SQL はマネージドなリレーショナルデータベースだが、秒間 8,500 件の書き込みを捌く水平スケーラビリティに限界がある。", "Cloud Spanner は強い整合性が要るリレーショナルデータ向け。クリックストリームのような単純な大量書き込みには、コストと機能の面で過剰。", "Cloud Storage は非構造化データ向けのオブジェクトストレージ。秒間数千件の個別書き込みを受けるデータベース用途には適さない。", "正解。秒間数百万リクエストまで扱えるフルマネージドの NoSQL で、時系列データの保存に向く。ノードを足せば処理能力も伸びる。"]}'),

  ('gcp-pca-g-q38', 'セキュリティとコンプライアンス',
   'あなたは大手Eコマース企業のクラウドセキュリティリードです。最近実施された社内のセキュリティ監査において、自社のGoogle Cloudプロジェクト内に未承認の新しいVPCネットワークが構築されていることが発覚しました。このネットワーク上のCompute Engineインスタンスでは、SSHポート（TCP/22）が全世界に向けて開放される設定になっていました。あなたは、この不適切なネットワークが作成された際の操作記録を特定したいと考えています。要件を達成するためにあなたがすべきことは何ですか？',
   NULL::text,
   '["Cloud Monitoring（旧Stackdriver）のアラートコンソールにアクセスし、「VMの作成」に関連するアラート履歴を検索する。", "Google Cloudコンソールの[ログ]セクションへ移動し、リソースとして[GCE ネットワーク]を指定した上で、[insert]や[create]のアクションに関連するログエントリを検索する。", "[ホーム]セクションの[アクティビティ]ページを表示し、カテゴリを「データアクセス」に設定した状態で、「VMの作成」に関連する操作ログを検索する。", "プロジェクトレベルのSSHキーを利用してCompute Engineインスタンスに接続し、OSのシステムログから過去のログイン履歴を確認して、それらをプロジェクトのオーナーリストと照合する。"]',
   1, '[1]', 'single',
   '{"asked": "誰がいつ不正な VPC を作ったのかを、記録から特定する方法。", "point": "リソースの作成・変更を追うなら Cloud Logging の管理者アクティビティログ。読み取りを追うのはデータアクセスログ。", "kid": "Google Cloud は「誰が、いつ、何をしたか」を監査ログとして自動で残している。作成や設定変更のような管理操作を記録するのが管理者アクティビティログで、これは最初から有効。データの中身を読んだ記録（データアクセスログ）は別枠で、こちらは自分で有効にしないと残らない。", "eg": "建物の記録に例えると、管理者アクティビティログは「誰が新しい部屋を増築したか」の工事記録、データアクセスログは「誰がその部屋に入って書類を見たか」の入室記録。増築した人物を探すなら工事記録を見る。", "terms": [["Cloud Audit Logs", "操作履歴を記録する仕組み。管理者アクティビティ、データアクセス、システムイベント、ポリシー拒否の 4 種類がある。"], ["管理者アクティビティログ", "リソースの作成・削除・設定変更を記録する。既定で有効で、無効にできない。"], ["データアクセスログ", "データの読み取りなどを記録する。量が多くなるため既定では無効。"], ["Cloud Logging", "ログを保存・検索・分析する統合サービス。リソースの種類と操作名で絞り込める。"]], "think": "探しているのは「VPC ネットワークが作られた」という管理操作の記録。まずログの種別を選び分ける。データアクセスログは読み取りの記録なので、作成操作はそこに出てこない。Cloud Monitoring は稼働状況やパフォーマンスの監視で、そもそも操作履歴を検索する道具ではない。VM 内の OS ログはインスタンスの中の話で、プロジェクトレベルの VPC 作成には届かない。残るのは Cloud Logging で、リソースの種類を GCE ネットワークに絞り、insert や create といった操作名で引く方法。これが管理者アクティビティログの正しい引き方になる。", "vs": "監査ログの 2 種の区別が本丸。作った・消した・変えた は管理者アクティビティ（既定で有効）、読んだ はデータアクセス（要有効化）。", "why_asked": "インシデント対応で最初に触るのが監査ログ。種別を取り違えると「ログが無い」と誤解して調査が止まる。", "usecase": "セキュリティ監査での特定に加えて、同じログをもとに「VPC 作成をアラートする」ログベースの指標を作り、再発を検知する仕組みにつなげる。", "opt": ["Cloud Monitoring はパフォーマンスや稼働状況の監視用。過去の管理操作の履歴を検索する用途には向かない。", "正解。管理者アクティビティログにリソースの作成が記録されている。リソースを GCE ネットワークに絞り、insert や create で引けば、誰がいつ作ったかを特定できる。", "データアクセスログは読み取り操作の記録。リソースの作成や設定変更は、管理者アクティビティログのほうに残る。", "OS のシステムログはインスタンス内部のログイン履歴。プロジェクトレベルの VPC 作成やファイアウォール変更は特定できない。"]}'),

  ('gcp-pca-g-q40', '設計・計画',
   'あなたは教育（eラーニング）プラットフォームを運営する企業のクラウドアーキテクトです。新規アプリケーションの基盤選定において、開発チームのマネージャーから以下の要件をすべて満たす構成を特定するよう求められました。

1. 特定のクラウドベンダーへのロックインを避けるため、オープンソース技術をベースとした移植性を備えること
2. 受講生の増減に合わせて、計算リソースを動的にオートスケーリングできること
3. 継続的デリバリー（CD）によるソフトウェアの迅速なリリースをサポートすること
4. 開発・検証など、同一のスタックを論理的に分離した状態で複数実行できること
5. 動的なテンプレートを利用して、アプリケーションのパッケージを容易にデプロイできること
6. URL パスに基づいて、ネットワークトラフィックを適切なサービスへルーティングすること

これらの要件をすべて達成するために、あなたが選択すべきテクノロジーの組み合わせはどれですか？',
   NULL::text,
   '["Google Kubernetes Engine, Cloud Build, Terraform", "Google Kubernetes Engine, Cloud Deployment Manager", "Google Kubernetes Engine, Jenkins, Helm", "Google Kubernetes Engine, Jenkins, Cloud Load Balancing"]',
   2, '[2]', 'single',
   '{"asked": "6 つの要件をすべて満たす、オープンソース中心の技術の組み合わせ。", "point": "「ベンダーロックインを避ける」が要件にあるなら、GCP 独自サービス（Cloud Build や Deployment Manager）を含む案はすべて落ちる。", "kid": "ベンダーロックインとは、特定のクラウド独自の道具に依存して、他社へ移りにくくなる状態のこと。Kubernetes・Jenkins・Helm はどれもオープンソースで、他社クラウドでもオンプレでも同じものが動く。Helm は Kubernetes 向けに「アプリの設定を穴埋め式のテンプレートにして配る」道具で、要件の「動的なテンプレートでパッケージをデプロイ」にそのまま対応する。", "eg": "電源プラグの形に似ている。世界共通の規格で作っておけば引っ越し先でもそのまま挿せるが、独自形状にすると変換器なしでは使えない。", "terms": [["Google Kubernetes Engine (GKE)", "オープンソースの Kubernetes をマネージドで動かすサービス。基盤自体はどこでも動く規格。"], ["Helm", "Kubernetes アプリをテンプレート化して配布・更新するパッケージマネージャー。"], ["Jenkins", "オープンソースの CI/CD ツール。どのクラウドでも動く。"], ["Ingress", "URL のパスで通信の行き先を振り分ける Kubernetes の標準リソース。GKE では追加コンポーネントなしで使える。"], ["Namespace", "同じクラスター内でスタックを論理的に分離する Kubernetes の仕組み。開発と検証の並行運用に使う。"]], "think": "6 つの要件のうち、GKE だけで満たせるものを先に消す。オートスケーリング、論理的な分離（Namespace）、URL パスによるルーティング（Ingress）は、いずれも Kubernetes が標準で持っている。残るのは、ベンダーロックインの回避、継続的デリバリー、動的テンプレートによるパッケージデプロイの 3 つ。ロックイン回避という条件があるので、Cloud Build も Deployment Manager も Google 独自であるため使えない。継続的デリバリーを担うオープンソースが Jenkins、動的テンプレートによるパッケージ管理を担うのが Helm。よって GKE・Jenkins・Helm の 3 点で 6 要件が埋まる。", "vs": "Cloud Load Balancing を挙げた案が紛らわしい。GKE では Ingress を作れば裏で負荷分散が用意されるので、別要素として数える必要がない。それより Helm が抜けていることのほうが致命的。", "why_asked": "要件が 6 つ並ぶ設問は、1 つずつ照合させるための形。すべてを 1 つの技術で満たそうとせず、要件を技術に割り振れるかを見ている。", "usecase": "マルチクラウドや将来のオンプレ回帰を視野に入れる企業の標準構成。Helm チャートにしておけば、同じアプリを開発・検証・本番へ値だけ変えて配れる。", "opt": ["Cloud Build は Google Cloud 独自のマネージドサービスなので、ベンダーロックインを避けるという要件に反する。", "Cloud Deployment Manager も Google Cloud 独自のツール。移植性の確保にも、Helm のような動的なパッケージングにも向かない。", "正解。GKE がオートスケーリングと Ingress によるパスルーティングを担い、Jenkins が継続的デリバリー、Helm が動的テンプレートによるパッケージ管理を担う。いずれもオープンソース由来で移植性も保てる。", "GKE は Ingress で負荷分散をネイティブに提供するので個別に挙げる必要がなく、動的テンプレートの要件を満たす Helm が抜けている。"]}'),

  ('gcp-pca-g-q41', '信頼性の確保',
   'あなたはオンライン証券会社のSREです。自社のユーザーフィードバックポータルは、us-central1リージョンの2つのゾーンに冗長化された標準的なLAMPスタックで構築されています。データベース以外のすべてのレイヤーには、オートスケーリングが有効なマネージドインスタンスグループが採用されています。現在は特定顧客のみに限定公開されており、99.99%のSLAを達成していますが、次四半期からは未登録ユーザーを含む全ユーザーへ開放する予定です。急激なトラフィック増加が発生してもSLAを維持できるレジリエンスを検証するため、テスト戦略を立案する必要があります。要件を達成するためにあなたがすべきことは何ですか？',
   NULL::text,
   '["既存ユーザーのトラフィックをキャプチャし、リソース使用率が80%に達するまでその負荷を再現します。また、現在の利用状況から将来のユーザー数を予測し、想定される最大負荷の200%を常時処理可能なリソースをあらかじめ配備します。", "現行ユーザーの操作ログを収集し、全レイヤーでオートスケーリングがトリガーされるまでその負荷をシミュレートします。その際、片方のゾーンにあるすべてのリソースを強制終了させて挙動を観察します。", "新しいポータルを段階的にユーザーグループへ公開し、全レイヤーでスケーリングロジックが動くまで日ごとにグループ規模を拡大します。併せて、両方のゾーンでランダムなリソースを停止させます。", "ランダムなユーザー入力を生成して、少なくとも1つのレイヤーでオートスケーリングが作動するまで負荷をかけます。同時に、両方のゾーンでランダムにリソースを停止させるカオスエンジニアリングを導入し、システムの耐性を確認します。"]',
   3, '[3]', 'single',
   '{"asked": "全ユーザー開放の前に、急なトラフィック増と障害への耐性を検証するテスト戦略。", "point": "「これから来る未知の負荷」は既存ログの再生では作れない。ランダムな入力で限界まで押し、同時にランダムに壊して確かめる。", "kid": "カオスエンジニアリングとは、わざと本番に近い環境でリソースを壊してみて「壊れても止まらないか」を確かめる手法。冗長構成は作っただけでは効くかどうか分からず、実際に落としてみて初めて確認できる。", "eg": "避難訓練に似ている。非常口の場所を図面で確認するだけでは、当日ちゃんと逃げられるか分からない。実際にベルを鳴らして走ってみる。", "terms": [["カオスエンジニアリング", "意図的に障害を注入して、システムの回復力を実地で検証する手法。"], ["レジリエンス", "障害の影響を最小に抑え、自動的に元の状態へ戻れる能力。"], ["マネージドインスタンスグループ（MIG）", "同じ構成の VM を束ね、オートスケーリングと自動修復を提供する仕組み。"], ["SLA", "提供者が約束するサービス品質の基準。99.99% は年間の停止が約 1 時間以下という水準。"]], "think": "検証したいのは 2 つある。未知のユーザーが押し寄せたときにスケールが追いつくか、そして一部が壊れてもサービスが続くか。前者について、これから来るのは未登録ユーザーなので、既存ユーザーの操作ログを再生しても行動の幅を再現できない。ランダムな入力を生成してこそ、想定外の経路を踏める。後者について、片方のゾーンを丸ごと落とすのは極端な一撃で、部分的な欠落に耐えられるかは分からない。両ゾーンでランダムに壊すほうが、現実に起きる散発的な障害に近い。またリソースを常時多めに用意しておく案は、オートスケーリングが実際に動くかを検証しないまま費用だけかける形になる。以上から、ランダム入力での負荷とランダム停止のカオスエンジニアリングを組み合わせる案が残る。", "vs": "段階的な公開（カナリアリリース）は本番投入のリスクを下げる手法で、事前に限界を測るテストではない。目的が違う。", "why_asked": "「冗長構成にしたから大丈夫」で止まる思考を突いている。設計しただけの可用性は検証されていない、という SRE の前提を知っているかを見る。", "usecase": "大規模キャンペーンや一般公開の前。本番に近い環境で負荷試験と障害注入を同時にかけて、SLO を割らないかを確かめる。", "opt": ["最大負荷の 200% を常時配備するのはコスト効率が悪く、オートスケーリングが実際に働くかを検証したことにもならない。", "現行ユーザーのログだけでは新規ユーザーの多様な行動を再現できない。片方のゾーンを丸ごと落とすのも極端で、散発的な障害への耐性は測れない。", "段階的な公開はデプロイ時のリスクを下げる手法。開放後に来る急増に耐えられるかを事前に検証する戦略にはならない。", "正解。ランダムな入力で未知のユーザー行動に近い負荷をかけ、同時に両ゾーンでランダムに停止させることで、スケールと冗長性の両方を実地で確認できる。"]}'),

  ('gcp-pca-g-q42', 'セキュリティとコンプライアンス',
   'あなたは人事系 SaaS を提供する企業のクラウドアーキテクトです。自社のプラットフォームにおいて、利用料金の支払いのためにクレジットカード決済を導入することになりました。PCI DSS（Payment Card Industry Data Security Standard）の準拠対象となる範囲を極力限定しつつ、決済データの傾向や利用されている支払い手段に関するトレンド分析を継続的に実施できる体制を整えたいと考えています。要件を達成するためにあなたがすべきことは何ですか？',
   NULL::text,
   '["決済処理を担うコンポーネントを独立したサブネットワーク内に配置し、ネットワークレベルでの分離を徹底する。", "独自のトークナイザサービスを構築し、機密情報を変換したトークンデータのみをデータベースに格納するように設計する。", "PCI 準拠に関わるデータを扱う全仮想マシン（VM）に特定のラベルを付与し、監査時のリソース特定プロセスを簡略化する。", "Google BigQuery へのログ出力を有効化した上で、アクセス制御リスト（ACL）やビュー機能を活用し、監査担当者が閲覧できる情報の範囲を制限する。", "カード決済情報の処理に特化した専用のプロジェクトを別途立ち上げ、他のワークロードから分離して管理する。"]',
   1, '[1]', 'single',
   '{"asked": "PCI DSS の対象範囲を最小にしつつ、決済データの傾向分析は続けられる設計。", "point": "スコープを減らすとは「カードの生情報が存在する場所を減らす」こと。分離や権限管理では減らない。トークンに置き換える。", "kid": "PCI DSS は、カード情報を扱うシステムに課される厳しいセキュリティ基準で、カードの生情報が通る場所・保存される場所すべてが対象になる。トークン化は、カード番号を意味を持たない別の文字列（トークン）に置き換えて保存するやり方。トークンからは元の番号を復元できないので、その保存場所は基準の対象から外れる。しかも同じカードには同じトークンが割り当たるので、傾向分析は続けられる。", "eg": "図書館の利用者番号に似ている。貸出履歴を分析するのに氏名や住所は要らず、利用者番号だけあれば「この人は月に何冊借りる」が分かる。氏名の台帳は 1 か所の金庫にしまい、他の部署には番号だけ渡す。", "terms": [["PCI DSS", "カード情報を安全に扱うための国際的なセキュリティ基準。対象範囲が広いほど監査の負担が増える。"], ["トークン化", "機密データを、元の値と数学的な関連がない代用値に置き換える手法。復元は変換元のサービスだけができる。"], ["スコープの縮小", "基準の適用対象となるシステムの範囲を狭め、監査コストとリスクを下げる戦略。"], ["匿名化との違い", "匿名化は復元できないようにする処理。トークン化は限られた場所でだけ復元でき、決済処理を続けられる点が違う。"]], "think": "「スコープ」が何で決まるかを押さえると一本道になる。スコープは、カードの生情報が保存・処理・伝送される範囲で決まる。ネットワークを分ける、プロジェクトを分ける、ラベルを付ける、閲覧権限を絞る、これらはいずれも生情報が存在する場所そのものを減らしていない。境界を引き直したり見えにくくしたりしているだけで、生情報を持つコンポーネントは残り続けるので、対象範囲も残る。トークン化だけが、生情報を持つ場所をトークナイザ 1 点に閉じ込め、他のシステムからは意味のない代用値しか見えない状態を作る。結果として対象範囲が本当に縮み、しかもトークンのまま集計できるので分析の要件も同時に満たす。", "vs": "「分離すればスコープが減る」は誤解。分離は監査の対象を整理して管理しやすくするが、対象そのものは減らない。減らすには、そこにデータを置かないようにするしかない。", "why_asked": "コンプライアンスの設問では、どれも真っ当なセキュリティ施策が並ぶ。「やったほうがよいこと」と「設問が求めるスコープ縮小」を区別できるかを見ている。", "usecase": "SaaS が決済を組み込むときの定石。トークン化は自前で作らず決済代行のサービスに任せ、自社の DB にはトークンと金額・日時だけを持つ形にすると、監査範囲がほぼ自社の外に出る。", "opt": ["ネットワークの分離は多層防御としては有効だが、生情報を扱うコンポーネントがシステム内に残るため、対象範囲そのものは減らない。", "正解。生情報の保存場所をトークナイザ周辺に閉じ込められるので、対象範囲が実際に縮む。トークンのまま集計できるので傾向分析も続けられる。", "ラベルの付与は監査時にリソースを見つけやすくする運用上の工夫にすぎず、準拠要件や対象範囲を減らす効果はない。", "アクセス制御やビューは閲覧権限の管理には有効だが、生データがシステム内に存在する限り対象範囲は縮まらない。", "プロジェクトを分ければ境界は作れるが、カードの生情報を処理・保持し続けるため、対象となるリソースの削減にはならない。"]}'),

  ('gcp-pca-g-q47', 'インフラのプロビジョニングと管理',
   'あなたはオンライン証券会社に所属するクラウドアーキテクトです。新規開発プロジェクトの一環として、ステートフルな特性を持つワークロードを Google Cloud 上に展開する計画を立てています。このワークロードは水平方向への拡張が可能ですが、稼働するすべてのインスタンスが同一の POSIX 準拠ファイルシステムに対して読み書きを行える環境が必要です。さらに、取引が集中する高負荷時には、共有ストレージに対して最大 100MB/s の書き込みスループットを維持しなければなりません。要件を達成するためにあなたがすべきことは何ですか？',
   NULL::text,
   '["Cloud Filestore インスタンスをプロビジョニングし、すべてのインスタンスにネットワーク経由でマウントして共有ストレージとして利用する。", "Cloud Storage バケットを作成し、gcsfuse を利用して各インスタンスのローカルディレクトリにマウントする。", "各インスタンスに対して、標準的な永続ディスクをアタッチしてローカルストレージとして運用する。", "データの可用性を高めるため、各コンピューティングインスタンスにリージョナル永続ディスクを個別に割り当てる。"]',
   0, '[0]', 'single',
   '{"asked": "複数インスタンスが同じ POSIX ファイルシステムに読み書きする共有ストレージの選定。", "point": "「複数台から同じファイルシステムを共有」と「POSIX 準拠」が揃ったら Cloud Filestore。永続ディスクは 1 台用、Cloud Storage はファイルシステムではない。", "kid": "POSIX 準拠とは、普通の Linux のファイル操作（開く・書く・ロックする）がそのまま効く、という意味。Filestore は、NFS というネットワーク越しのファイル共有を Google がマネージドで提供するサービスで、複数の VM から同じフォルダを同時にマウントして読み書きできる。", "eg": "全員が同じ共有フォルダを開いている状態。永続ディスクは各自の PC の内蔵ドライブで、他の人からは見えない。", "terms": [["Cloud Filestore", "NFS ベースの共有ファイルストレージをマネージドで提供するサービス。複数インスタンスから同時にマウントできる。"], ["POSIX 準拠", "Unix 系の標準的なファイル操作の作法に従うこと。既存アプリを書き換えずに動かすために効く。"], ["gcsfuse", "Cloud Storage をファイルシステムのように見せるツール。見た目は似るが、POSIX の挙動を完全には再現できない。"], ["リージョナル永続ディスク", "2 つのゾーンに同期複製される永続ディスク。可用性は上がるが、複数台からの同時読み書きを目的とはしていない。"]], "think": "要件は 2 つ。すべてのインスタンスが同じファイルシステムに読み書きできること、そして POSIX 準拠であること。永続ディスクは基本的に 1 つのインスタンスに付けて使うものなので、前者で落ちる。リージョナル永続ディスクは複製先が増えるだけで、共有ファイルシステムとして複数台に同時に書かせる仕組みではないので同様。Cloud Storage に gcsfuse をかぶせるとフォルダのように見えるが、中身はオブジェクトストレージなので、ファイルの部分更新やロックといった POSIX の挙動が期待どおりにならず、高頻度の書き込み性能も保証できない。NFS をそのまま提供する Filestore だけが両方を満たし、100MB/s の書き込みスループットにも対応する。", "vs": "gcsfuse は「マウントできる＝共有ファイルシステム」という誤解を生みやすい。マウントできることと、POSIX の意味論が守られることは別。", "why_asked": "ステートフルなワークロードの移行では、共有ファイルシステムの要求が頻繁に出る。オブジェクトストレージで代用できるかを判断できるかが問われる。", "usecase": "レガシーな業務アプリや、複数の処理ノードが同じ作業ディレクトリを見るバッチ基盤。GKE でも Filestore を複数 Pod から読み書きできるボリュームとして使える。", "opt": ["正解。フルマネージドの NFS ファイルストレージで、複数インスタンスから同じ POSIX 準拠のファイルシステムを共有できる。100MB/s 規模の書き込みにも対応する。", "Cloud Storage はオブジェクトストレージで、gcsfuse を使っても完全な POSIX 準拠や高頻度の書き込み性能は保証できない。", "標準的な永続ディスクは 1 つのインスタンスに付けて使う設計で、複数インスタンス間でのファイル共有ができない。", "リージョナル永続ディスクはデータの冗長性を高めるが、複数インスタンスから同時に読み書きする共有ファイルシステムの機能は持たない。"]}'),

  ('gcp-pca-g-q50', 'セキュリティとコンプライアンス',
   'あなたは、Cresswell Health Systems における Google Cloud の利用状況が、近日実施されるプライバシーおよび規制コンプライアンスの監査基準を確実にクリアできるよう準備を進めています。この監査への対応として、実施すべきアクションを2つ選択してください。',
   NULL::text,
   '["デプロイされるすべての Kubernetes ワークロードに対して、GKE プライベートクラスターの利用を必須化する。", "Cresswell Health Systems が Google Cloud との間でビジネスアソシエイト契約（BAA）を正式に締結していることを確認、または締結するよう助言する。", "Web ベースのアプリケーションにおけるセキュリティ脅威の検知および防御を目的として、Prometheus を環境に導入する。", "Google Cloud のコンプライアンスポータルにある準拠サービス一覧を確認し、Cresswell Health Systems が利用している各プロダクトがそのリストに含まれているか照合する。", "Cresswell Health Systems の提供するユーザー向けアプリケーションの認証システムとして Firebase Authentication を実装する。"]',
   1, '[1, 3]', 'multi',
   '{"asked": "医療データを扱う組織がコンプライアンス監査に備えて取るべき、2 つのアクション。", "point": "医療データなら、まず契約（BAA）を締結しているか、次に使っているサービスが準拠一覧に載っているか。技術の追加より先にこの 2 点。", "kid": "HIPAA は米国の医療情報保護法。クラウドを使って医療情報を扱うには、クラウド事業者との間で BAA（ビジネスアソシエイト契約）という、責任範囲を定めた契約を結ぶ必要がある。さらに Google Cloud の全サービスが HIPAA の対象になっているわけではないので、自分たちが使っている製品が対象リストに入っているかを 1 つずつ確かめる。", "eg": "飲食店の営業許可に似ている。まず保健所と手続きを済ませ（契約）、次に使っている設備が許可の対象に入っているかを確認する（一覧の照合）。厨房を綺麗にするだけでは許可は下りない。", "terms": [["BAA（ビジネスアソシエイト契約）", "HIPAA に基づき、医療情報を預かる事業者と結ぶ契約。責任範囲を明確にする。"], ["HIPAA", "米国の、医療情報のプライバシーとセキュリティに関する法令。"], ["コンプライアンスポータル", "Google Cloud が各規制への準拠状況と対象サービス一覧を公開しているサイト。"], ["対象サービス", "その規制のもとで利用が認められているサービスの一覧。載っていないサービスで医療情報を扱ってはいけない。"]], "think": "コンプライアンス監査で問われるのは「技術的にどれだけ堅牢か」ではなく「定められた要件を満たしている証拠があるか」。この視点で選択肢を見る。プライベートクラスターの必須化も認証基盤の実装も、セキュリティとしては意味があるが、監査基準がそれを一律に要求しているわけではないので証拠にはならない。監視ツールの導入も同様で、そもそも脅威の検知と防御を担うものでもない。一方、BAA の締結は HIPAA が明確に求める前提条件で、これが無ければ他が完璧でも成立しない。そして対象サービス一覧との照合は、使っている製品が規制の枠内かを示す唯一の確認手段になる。この 2 つが監査対応として必須のアクションになる。", "vs": "「セキュリティを強くする施策」と「コンプライアンスを満たす手続き」は別の話。監査では後者が問われる。", "why_asked": "技術者は技術的な対策を選びたくなる。規制対応では契約と対象範囲の確認が先、という順序を知っているかを見ている。", "usecase": "医療・金融・公共のクラウド利用開始時。まず契約を結び、対象サービス一覧をもとに設計で使う製品を確定させてから、アーキテクチャを描き始める。", "opt": ["プライベートクラスターはネットワークの安全性を高めるが、監査基準として一律に必須とされる要件ではない。", "正解。HIPAA のもとで医療情報をクラウドで扱うには、Google Cloud との BAA 締結が前提になる。責任範囲がここで明確になる。", "Prometheus はメトリクスの監視とアラートのツール。セキュリティ脅威の検知や防御を担うものではなく、コンプライアンス対策にもならない。", "正解。Google Cloud の全サービスが規制の対象になっているわけではないため、使っている製品が準拠サービス一覧に含まれるかの照合が要る。", "Firebase Authentication は認証機能を提供するサービス。導入したこと自体がコンプライアンス監査の合格を保証するわけではない。"]}')

) AS v(source_ref, category_name, question_text, code, options,
       correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'gcp-pca-g'
ON CONFLICT (subject_id, source_ref) DO NOTHING;


COMMIT;

